"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5367"],{2224(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>m,frontMatter:()=>r,contentTitle:()=>s,toc:()=>d,assets:()=>l});var a=JSON.parse('{"id":"reference/hardware/protocols/mqtt-dm","title":"MQTT device management","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/hardware/protocols/mqtt-dm.md","sourceDirName":"reference/hardware/protocols","slug":"/reference/hardware/protocols/mqtt-dm","permalink":"/personal-av-docs/docs/reference/hardware/protocols/mqtt-dm","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/hardware/protocols/mqtt-dm.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"MQTT device management","sidebar_label":"MQTT device management","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-dm","format":"md"}}'),i=t(4848),o=t(8453);let r={title:"MQTT device management",sidebar_label:"MQTT device management",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-dm",format:"md"},s,l={},d=[];function c(e){let n={a:"a",code:"code",p:"p",pre:"pre",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:[":::note Edition\n",(0,i.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(n.a,{href:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-dm",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsxs)(n.p,{children:['MQTT device management\nInitializing Table Of Contents...\nIntroduction\nThis page explains how to manage your devices with AirVantage when using MQTT.\nYou may use MQTT for application communication (pushing values to AirVantage and receiving commands or settings). Most of the time you are using one of our bit-pipe modems (HL) or a legacy 3rd party hardware.\nIn such case, you need to upgrade the firmware and software (Linux or MCU behind the bit-pipe modem) of your device in order to fix security issues, deploy new features \u2026 Implementing an OMA-DM or LWM2M stack is seen as overkill for what is a simple command with a URL to send to the MQTT client.\nLet\u2019s outline some simple workflows for managing the firmware/software of devices connected using MQTT.\nSoftware management\nInstall\nYou can use AirVantage to send install and uninstall software commands to your MQTT client.\nYour application model needs to have the device management actions\nMQTT_SW_INSTALL\nand\nMQTT_SW_UNINSTALL\n.\nTo install an application you must use the application manager\nMQTT_SW\n.\n<?xml version="1.0" encoding="ISO-8859-1"?>\n<app:application\nxmlns:app="',(0,i.jsx)(n.a,{href:"http://www.sierrawireless.com/airvantage/application/1.0",children:"http://www.sierrawireless.com/airvantage/application/1.0"}),'"\ntype="com.test.dm.airvantage.app"\nname="Software Management with AirVantage"\nrevision="0.1">\n<capabilities>']}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'&lt;communication&gt;\n  &lt;protocol comm-id="SERIAL" type="MQTT" /&gt;\n&lt;/communication&gt;\n\n&lt;dm&gt;\n  &lt;action impl="MQTT_SW_INSTALL"/&gt;\n  &lt;action impl="MQTT_SW_UNINSTALL"/&gt;\n&lt;/dm&gt;\n'})}),"\n",(0,i.jsx)(n.p,{children:"</capabilities>"}),"\n",(0,i.jsxs)(n.p,{children:['<application-manager use="MQTT_SW"/>\n</app:application>\nFor more details about the application model, see:\nApplication model reference\n.\nThe AirVantage server sends installation/uninstallation tasks using the\n{IMEI or SN}/tasks/json\ntopic.\nHere\u2019s an example of an install task, using the topic format:\n[\n{\n"uid" : "e87b35c3c2e2417b902277ff9d049d70",\n"timestamp" : 1416324560869,\n"swinstall" : {\n"type":"My Application",\n"revision": "1.1",\n"url":"',(0,i.jsx)(n.a,{href:"https://eu.airvantage.net/devicev4/dl/b79e1772482b4d70a6bca18c461163d2/4e51d63280b6489a90b3a5c6c75d3189/full.bin",children:"https://eu.airvantage.net/devicev4/dl/b79e1772482b4d70a6bca18c461163d2/4e51d63280b6489a90b3a5c6c75d3189/full.bin"}),'"\n}\n},\n...\n]\nThe command name is\nswinstall\n, the arguments are: the application type and the download URL:\ntype\n: is the unique identifier of your application. If an application of this type is already installed you must replace it.\nrevision:\nthe revision of the application to install.\nurl\n: the URL for downloading the binary package to be installed.\nSuccess and error must be reported in the same way as for other tasks by publishing on\n{IMEI or SN}/acks/json\n.\nThe application type should be unique per device, so if an application with the same application type is already installed, it should be replaced\n(upgraded) by the new one.\nUninstall\nHere\u2019s an example of the\nswuninstall\ncommand:\n[\n{\n"uid" : "e87b35c3c2e2417b902277ff9d049d70",\n"timestamp" : 1416324560869,\n"swuninstall" : {\n"type":"My Application",\n}\n},\n...\n]\nIf an application of the given type is installed, you must uninstall it and report success/failure on\n{IMEI or SN}/asks/json\n.\nSoftware synchronization\nOptionally, the device may expose some data about the installed software to the server for synchronizing.\nThe data DM.SW should contain the list of installed software separated by \u201C;\u201D like: \u201CMYAPP;MONITORING_APP\u201D\nThe data DM.SW.VER should contain the list of versions corresponding to the installed software separated by \u201C;\u201D like: \u201C123.5.6;v2-beta\nConnectivity & device monitoring\nWith the MQTT protocol you can use JSON messages to publish and subscribe to device data messages. A list of supported data\nFields\nare listed below:\nData\nType\nDescription\nData\nType\nDescription\n_APN\nstring limited to 255 char\nThe APN used by the device\n_OPERATOR\nstring limited to 255 char\nThe network operator used by the device to communicate\n_BYTES_SENT\nlong\nNumber of bytes sent by the device\n_PACKETS_SENT\nlong\nNumber of packets sent by the device\n_BYTES_RECEIVED\nlong\nNumber of bytes received by the device\n_PACKETS_RECEIVED\nlong\nNumber of packets received by the device\n_CELL_ID\nstring limited to 255 char\nCell identifier use for the cellular communication\n_RSSI\ndouble\nThe Received signal strength indicator (between -70 and -100)\n_ECIO\ndouble\nThe signal quality (values between -5 and -15).\n_RSSI_LEVEL\nstring\nThe level of RSSI computed from the raw value:\nEXCELLENT (min : -70),\nGOOD (min: -85, max: -70),\nFAIR (min: -100, max: -85),\nPOOR (max: -100).\n_ECIO_LEVEL\nstring\nThe level of Ec/Io computed from the raw value:\nEXCELLENT (min: -5),\nGOOD (min: -10, max: -5),\nFAIR (min: -15, max: -10),\nPOOR (max: -15).\n_RSRP\ndouble\n(LTE only) The Reference Signal Received Power (dBm) - in\n1\n\u2044\n10\ndBm.\n_ICCID\nstring limited to 30 char\n_RSRP_LEVEL\nstring\nThe level of RSRP computed from the raw value:\nEXCELLENT (min : -90),\nGOOD (min: -105, max: -90),\nFAIR (min: -120, max: -105),\nPOOR (max: -120).\n_IP_ADDRESS\nstring limited to 100 char\nThe IP Address used by the device to communicate with AirVantage\n_RSRQ\ndouble\n(LTE only) The Reference Signal Received Quality (dB) - in\n1\n\u2044\n10\ndB.\n_LATITUDE\ndouble\nFormat: Signed degrees format (DDD.dddd).\nA latitude with 8 decimal places pinpoints a location to within 1 millimeter,(\n1\n\u2044\n16\ninch):\nPrefix South latitudes with a minus sign.\nLatitudes range from -90 to 90.\nExample: 41.25\n_RSRQ_LEVEL\nstring\nThe level of RSRQ computed from the raw value:\nEXCELLENT (min : -9),\nGOOD (min: -12, max: -9),\nFAIR_TO_POOR (max: -12).\n_LONGITUDE\ndouble\nFormat: Signed degrees format (DDD.dddd).\nA longitude with 8 decimal places pinpoints a location to within 1 millimeter,(\n1\n\u2044\n16\ninch):\nPrefix West longitudes with a minus sign.\nLongitudes range from -180 to 180.\nExample: -120.9762\n_SIM_OPERATOR\nstring limited to 50 char\nThe operator which provided the SIM\n_MOBILE_NUMBER\nstring limited to 30 char\n_SIGNAL_BARS\ninteger\nNO_REPORT(null),\nNO_SIGNAL(0),\nVERY_LOW(1),\nLOW(2),\nGOOD(3),\nVERY_GOOD(4),\nEXCELLENT(5)\n_NETWORK_SERVICE_TYPE\nstring limited to 255 char\nType of wireless service the device uses:\n\u201CNone\u201D,\n\u201CGPRS\u201D,\n\u201CEDGE\u201D,\n\u201CUMTS\u201D,\n\u201CHSDPA\u201D,\n\u201CHSUPA\u201D,\n\u201CHSPA\u201D,\n\u201C1X\u201D,\n\u201CEV-DO Rev.0\u201D,\n\u201CEV-DO Rev.A\u201D,\n\u201CLTE\u201D,\n\u201CUnknown\u201D']})]})}function m(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>s});var a=t(6540);let i={},o=a.createContext(i);function r(e){let n=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(o.Provider,{value:n},e.children)}}}]);